    /// <summary>
    /// Neutral (all v0.5 parameters zeroed) signatures produced by the actual <c>v0.4.0</c> tag
    /// sources, so <see cref="DroidVoiceProfileTests.NeutralV05Parameters_ReproduceLegacyAudio"/>
    /// keeps guarding real legacy compatibility across platforms.
    /// </summary>
    internal static readonly Dictionary<string, string> V04Legacy = new(StringComparer.Ordinal)
    {
        ["Hello, world!"] = "len=28801|rate=44100|rms=0.166164|peak=0.722774|mean=0.092534|dc=0.000759|zc=1178|clipped=0|cen=791.0|env=0.002043,0.288296,0.259163,0.276719,0.251266,0.063213,0.000000,0.239680,0.270612,0.130828,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000",
        ["Привет, как дела?"] = "len=40819|rate=44100|rms=0.119395|peak=0.498154|mean=0.074603|dc=0.000396|zc=1889|clipped=0|cen=1425.3|env=0.096408,0.161725,0.158034,0.168339,0.083948,0.103126,0.165600,0.089240,0.173441,0.179148,0.145265,0.054670,0.000000,0.000000,0.000000,0.000000",
    };

    internal static readonly Dictionary<string, string> Texts = new(StringComparer.Ordinal)
    {
        ["hello"] = "Hello, world!",
        ["hyphen"] = "R2-D2, are you okay?",
        ["ellipsis"] = "I am... not sure.",
        ["shout"] = "BEEP BOOP BOOP",
        ["cyrillic"] = "Привет, как дела?",
        ["pangram"] = "The quick brown fox jumps over the lazy dog.",
        ["excited"] = "WOW! THIS IS AMAZING! I LOVE IT!",
    };

    public static TheoryData<string, string, int> GoldenCases()
    {
        var data = new TheoryData<string, string, int>();

        foreach (var (textId, _) in Texts)
        {
            foreach (var profileName in new[] { "R2", "Grumpy", "Bass", "Tiny" })
            {
                foreach (var seed in new[] { 0, 12345 })
                {
                    data.Add(textId, profileName, seed);
                }
            }
        }

        return data;
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public void GoldenPcm_IsAcousticallyIdentical(string textId, string profileName, int seed)
    {
        var text = Texts[textId];
        var profile = Profile(profileName);
        var synthesizer = new DroidSynthesizer(seed: seed, profile: profile);

        var samples = synthesizer.Synthesize(text);

        PcmFingerprint.AssertMatches(Golden[$"{textId}|{profileName}|{seed}"], samples, synthesizer.SampleRate);
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public void SampleCount_MatchesRenderedLength(string textId, string profileName, int seed)
    {
        var text = Texts[textId];
        var profile = Profile(profileName);
        var synthesizer = new DroidSynthesizer(seed: seed, profile: profile);

        var count = synthesizer.GetSampleCount(text);
        var samples = synthesizer.Synthesize(text);

        Assert.Equal(count, samples.Length);
        Assert.Equal(count, synthesizer.GetSampleCount(text));
    }

    [Fact]
    public void GoldenPcm_IsStableAtReducedSampleRate()
    {
        var synthesizer = new DroidSynthesizer(sampleRate: 22050, seed: 0, profile: DroidVoiceProfile.R2);

        var samples = synthesizer.Synthesize("Hello, world!");

        PcmFingerprint.AssertMatches(Golden["hello|R2|0|22050"], samples, synthesizer.SampleRate);
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public void SpanOverload_WritesTheSameBytesAsAllocatingOverload(string textId, string profileName, int seed)
    {
        // Both buffers come from the same process on the same platform, so this stays a strict
        // byte-for-byte check; only the cross-version goldens are platform tolerant.
        var text = Texts[textId];
        var profile = Profile(profileName);
        var synthesizer = new DroidSynthesizer(seed: seed, profile: profile);

        var expected = synthesizer.Synthesize(text);
        var destination = new float[synthesizer.GetSampleCount(text)];

        var written = synthesizer.Synthesize(text, destination);

        Assert.Equal(expected.Length, written);
        Assert.True(expected.AsSpan().SequenceEqual(destination));
    }

    internal static DroidVoiceProfile Profile(string name) => name switch
    {
        "R2" => DroidVoiceProfile.R2,
        "Grumpy" => DroidVoiceProfile.Grumpy,
        "Bass" => DroidVoiceProfile.Bass,
        "Tiny" => DroidVoiceProfile.Tiny,
        _ => throw new ArgumentOutOfRangeException(nameof(name), name, "Unknown profile."),
    };
}
